//! Required real password session producers on both migrated engines.
use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
use serde_json::{json,Value};use sqlx::{AnyPool,Connection,Column,Row};use tower::ServiceExt;
use std::{path::{Path,PathBuf},collections::BTreeMap,io::Read};use sha2::{Digest,Sha256};
const JWT:&str="owned-password-fixture-secret";const PASSWORD:&str="owned-fixture-password-not-a-real-account";
fn workspace()->PathBuf{PathBuf::from(std::env::var("STARLANE_PASSWORD_WORKSPACE").expect("required owned password workspace"))}
async fn pool(url:&str,schema:&str)->AnyPool{sqlx::any::install_default_drivers();let engine=crate::db::DatabaseEngine::from_url(url).unwrap();let schema=schema.to_owned();sqlx::any::AnyPoolOptions::new().max_connections(2).after_connect(move|c,_|{let schema=schema.clone();Box::pin(async move{match engine{crate::db::DatabaseEngine::Postgres=>{sqlx::query(&format!("SET search_path TO {schema}")).execute(c).await?;},crate::db::DatabaseEngine::Sqlite=>{sqlx::query("PRAGMA foreign_keys=ON").execute(&mut*c).await?;sqlx::query("PRAGMA busy_timeout=5000").execute(c).await?;}}Ok(())})}).connect(url).await.unwrap()}
fn state(db:AnyPool,root:&Path)->crate::AppState{crate::AppState{db,jwt_secret:JWT.into(),base_url:"http://owned.invalid".into(),search_index:crate::search::SearchIndex::new(root.join("search_index")).unwrap(),oauth_cache:crate::auth::routes::OAuthStateCache::new(),ws_rooms:crate::sync::WsRooms::default()}}

async fn call(s:&crate::AppState,token:Option<&str>,method:&str,uri:&str,body:Value)->(StatusCode,Value){println!("PASSWORD_STEP {method} {uri}");let mut q=Request::builder().method(method).uri(uri).header("Content-Type","application/json");if let Some(t)=token{q=q.header("Authorization",format!("Bearer {t}"));}let mut req=q.body(Body::from(body.to_string())).unwrap();req.extensions_mut().insert(axum::extract::ConnectInfo("127.0.0.1:43123".parse::<std::net::SocketAddr>().unwrap()));let r=crate::api_routes().with_state(s.clone()).oneshot(req).await.unwrap();let code=r.status();let bytes=to_bytes(r.into_body(),4*1024*1024).await.unwrap();(code,if bytes.is_empty(){Value::Null}else{serde_json::from_slice(&bytes).unwrap_or(json!({"non_json":true}))})}
async fn ok(s:&crate::AppState,token:Option<&str>,method:&str,uri:&str,body:Value)->Value{let(code,v)=call(s,token,method,uri,body).await;assert!(code.is_success(),"actual {method} {uri} status={code}; response suppressed to protect credentials");v}
fn access(v:&Value)->&str{v["access_token"].as_str().unwrap()}fn refresh(v:&Value)->&str{v["refresh_token"].as_str().unwrap()}fn sid(v:&Value)->String{crate::auth::jwt::validate_token(access(v),JWT,crate::auth::jwt::TokenType::Access).unwrap().sid}
async fn snapshot(db:&AnyPool,tables:&[&str])->BTreeMap<String,Vec<Value>>{let mut out=BTreeMap::new();for table in tables{let mut values=Vec::new();for row in sqlx::query(&format!("SELECT * FROM {table}")).fetch_all(db).await.unwrap(){let mut cells=BTreeMap::new();for col in row.columns(){let n=col.name();let v=if let Ok(v)=row.try_get::<Option<String>,_>(n){v.map(|v|json!(["text",v])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<i64>,_>(n){v.map(|v|json!(["integer",v.to_string()])).unwrap_or(json!(["null"]))}else if let Ok(v)=row.try_get::<Option<Vec<u8>>,_>(n){v.map(|v|json!(["blob",hex::encode(v)])).unwrap_or(json!(["null"]))}else{panic!("unsupported cell {table}.{n}")};cells.insert(n.to_string(),v);}values.push(serde_json::to_value(cells).unwrap());}values.sort_by_cached_key(Value::to_string);out.insert(table.to_string(),values);}out}
async fn denied(s:&crate::AppState,token:Option<&str>,method:&str,uri:&str,body:Value){let before=snapshot(&s.db,&["users","sessions"]).await;let files=bytes(&crate::storage::data_dir());let(code,_)=call(s,token,method,uri,body).await;assert_eq!(code,StatusCode::UNAUTHORIZED,"actual denial {method} {uri}");assert!(before==snapshot(&s.db,&["users","sessions"]).await,"denied request changed user/session rows");assert_eq!(files,bytes(&crate::storage::data_dir()),"denied request changed owned bytes");}
fn login_body(email:&str,password:&str)->Value{json!({"email":email,"password":password,"device_name":"Owned browser","session_kind":"browser","client_platform":"web"})}
async fn login(s:&crate::AppState)->Value{ok(s,None,"POST","/auth/login",login_body("owner@password.invalid",PASSWORD)).await}
async fn seed(db:&AnyPool){let hash=crate::auth::password::hash_password(PASSWORD).unwrap();for(id,email,active,hash)in[("password-owner","owner@password.invalid",1,Some(hash)),("password-inactive","inactive@password.invalid",0,Some(crate::auth::password::hash_password(PASSWORD).unwrap())),("password-provider","provider@password.invalid",1,None)]{sqlx::query("INSERT INTO users(id,email,display_name,role,account_kind,is_active,password_hash) VALUES($1,$2,$1,'member','member',$3,$4)").bind(id).bind(email).bind(active).bind(hash).execute(db).await.unwrap();}sqlx::query("INSERT INTO spaces(id,name,slug,visibility,created_by) VALUES('password-space','Password content','password-space','private','password-owner')").execute(db).await.unwrap();sqlx::query("INSERT INTO space_members(id,space_id,user_id,role) VALUES('password-member','password-space','password-owner','owner')").execute(db).await.unwrap();}
async fn flow(s:&crate::AppState)->Value{let a=login(s).await;assert_eq!(a["user"]["id"],"password-owner");assert_eq!(a["user"]["account_kind"],"member");let aid=sid(&a);let hash:String=sqlx::query_scalar("SELECT refresh_token_hash FROM sessions WHERE id=$1").bind(&aid).fetch_one(&s.db).await.unwrap();assert_eq!(hash,hex::encode(Sha256::digest(refresh(&a).as_bytes())));assert_ne!(hash,refresh(&a));assert_eq!(ok(s,Some(access(&a)),"GET","/auth/me",Value::Null).await["id"],"password-owner");
let page=ok(s,Some(access(&a)),"POST","/spaces/password-space/documents",json!({"source_id":"password-page","title":"Password stable content","content":"EXACT_PASSWORD_PAGE Ω","property_values":[]})).await;ok(s,Some(access(&a)),"POST",&format!("/spaces/password-space/documents/password-page/drafts/{}/publish",page["draft_id"].as_str().unwrap()),json!({})).await;
let content=snapshot(&s.db,&["documents","document_drafts","storage_journal_receipts","publication_receipts"]).await;let files=bytes(&crate::storage::data_dir());assert!(!files.is_empty());
for(email,pw)in[("owner@password.invalid","incorrect"),("missing@password.invalid",PASSWORD),("inactive@password.invalid",PASSWORD),("provider@password.invalid",PASSWORD)]{denied(s,None,"POST","/auth/login",login_body(email,pw)).await;}
denied(s,None,"POST","/auth/refresh",json!({"refresh_token":"invalid"})).await;denied(s,None,"POST","/auth/refresh",json!({"refresh_token":access(&a)})).await;denied(s,Some(refresh(&a)),"GET","/auth/me",Value::Null).await;
let b=login(s).await;assert_ne!(sid(&b),aid);let rows=ok(s,Some(access(&a)),"GET","/auth/sessions",Value::Null).await;assert_eq!(rows.as_array().unwrap().len(),2);assert!(rows.as_array().unwrap().iter().any(|r|r["id"]==aid&&r["is_current"]==true&&r["device_name"]=="Owned browser"));assert!(rows.as_array().unwrap().iter().any(|r|r["id"]==sid(&b)&&r["device_name"]=="Owned browser (2)"));
// Existing token design uses second-resolution claims; cross its real issuance boundary to observe rotation.
let issued=crate::auth::jwt::validate_token(refresh(&a),JWT,crate::auth::jwt::TokenType::Refresh).unwrap().iat;while chrono::Utc::now().timestamp()<=issued{tokio::time::sleep(std::time::Duration::from_millis(20)).await;}
let rotated=ok(s,None,"POST","/auth/refresh",json!({"refresh_token":refresh(&a)})).await;assert_eq!(sid(&rotated),aid);assert_ne!(refresh(&rotated),refresh(&a));denied(s,None,"POST","/auth/refresh",json!({"refresh_token":refresh(&a)})).await;
let expiry:String=sqlx::query_scalar("SELECT expires_at FROM sessions WHERE id=$1").bind(&aid).fetch_one(&s.db).await.unwrap();sqlx::query("UPDATE sessions SET expires_at='2000-01-01T00:00:00Z' WHERE id=$1").bind(&aid).execute(&s.db).await.unwrap();denied(s,Some(access(&rotated)),"GET","/auth/me",Value::Null).await;denied(s,None,"POST","/auth/refresh",json!({"refresh_token":refresh(&rotated)})).await;sqlx::query("UPDATE sessions SET expires_at=$1 WHERE id=$2").bind(expiry).bind(&aid).execute(&s.db).await.unwrap();
sqlx::query("UPDATE users SET is_active=0 WHERE id='password-owner'").execute(&s.db).await.unwrap();denied(s,None,"POST","/auth/login",login_body("owner@password.invalid",PASSWORD)).await;denied(s,None,"POST","/auth/refresh",json!({"refresh_token":refresh(&rotated)})).await;denied(s,Some(access(&rotated)),"GET","/auth/me",Value::Null).await;sqlx::query("UPDATE users SET is_active=1 WHERE id='password-owner'").execute(&s.db).await.unwrap();
ok(s,Some(access(&b)),"POST","/auth/logout",json!({})).await;denied(s,Some(access(&b)),"GET","/auth/me",Value::Null).await;denied(s,None,"POST","/auth/refresh",json!({"refresh_token":refresh(&b)})).await;assert_eq!(ok(s,Some(access(&rotated)),"GET","/auth/me",Value::Null).await["id"],"password-owner");assert!(content==snapshot(&s.db,&["documents","document_drafts","storage_journal_receipts","publication_receipts"]).await);assert_eq!(files,bytes(&crate::storage::data_dir()));println!("PASSWORD_ACTUAL_PRODUCER_DENIAL_PASS");json!({"active":rotated,"revoked":b,"files":files})}
fn bytes(root:&Path)->BTreeMap<String,String>{fn walk(root:&Path,p:&Path,out:&mut BTreeMap<String,String>){let m=std::fs::symlink_metadata(p).unwrap();assert!(!m.file_type().is_symlink());if m.is_dir(){for e in std::fs::read_dir(p).unwrap(){walk(root,&e.unwrap().path(),out);}}else{assert!(m.is_file());let mut f=std::fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0u8;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}out.insert(p.strip_prefix(root).unwrap().to_string_lossy().into(),hex::encode(h.finalize()));}}let mut out=BTreeMap::new();for n in["spaces",".storage-journal",".publication-journal",".canonical-rewrite-journal",".move-relocation-journal"]{let p=root.join(n);if p.exists(){walk(root,&p,&mut out);}}out}

async fn run(engine:&str){let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));std::fs::create_dir_all(&root).unwrap();let(url,schema)=if engine=="postgres"{let url=std::env::var("STARLANE_PASSWORD_PG_URL").expect("required owned PostgreSQL URL");assert!(url.starts_with("postgres://"));sqlx::any::install_default_drivers();let schema=format!("password_{}",uuid::Uuid::new_v4().simple());let mut c=sqlx::AnyConnection::connect(&url).await.unwrap();sqlx::query(&format!("CREATE SCHEMA {schema}")).execute(&mut c).await.unwrap();c.close().await.unwrap();(url,schema)}else{(format!("sqlite://{}?mode=rwc",root.join("starlane-notes.db").display()),String::new())};let db=pool(&url,&schema).await;crate::db::migrate_selected(&db,crate::db::DatabaseEngine::from_url(&url).unwrap()).await.unwrap();seed(&db).await;let s=state(db,&root);let e=flow(&s).await;std::fs::write(workspace().join("expected.json"),e.to_string()).unwrap();s.db.close().await;drop(s);let child=std::process::Command::new(std::env::current_exe().unwrap()).args(["postgres_password_fixture::fresh_password_child","--ignored","--exact","--nocapture"]).env("STARLANE_PASSWORD_CHILD_URL",url).env("STARLANE_PASSWORD_SCHEMA",schema).output().unwrap();assert!(child.status.success(),"{}\n{}",String::from_utf8_lossy(&child.stdout),String::from_utf8_lossy(&child.stderr));println!("PASSWORD_FRESH_CHILD {}",String::from_utf8_lossy(&child.stdout));}
#[tokio::test]#[ignore="required explicitly owned dual-engine password orchestration"]async fn required_postgres_password(){run("postgres").await;}
#[tokio::test]#[ignore="required explicitly owned dual-engine password orchestration"]async fn required_sqlite_password(){run("sqlite").await;}
#[tokio::test]#[ignore="only genuine required parent launches child"]async fn fresh_password_child(){let url=std::env::var("STARLANE_PASSWORD_CHILD_URL").expect("required genuine parent URL");let schema=std::env::var("STARLANE_PASSWORD_SCHEMA").expect("required genuine parent schema");let root=crate::storage::data_dir();assert!(root.starts_with(workspace()));let e:Value=serde_json::from_slice(&std::fs::read(workspace().join("expected.json")).unwrap()).unwrap();let db=pool(&url,&schema).await;crate::storage::restoration::bootstrap_gate(&root).unwrap();crate::storage::restoration::activate_in(&root,&db).await.unwrap();crate::storage::relocation::recover(&db).await.unwrap();crate::storage::journal::recover(&db).await.unwrap();crate::storage::canonical_rewrite::recover(&db).await.unwrap();crate::storage::publication::recover(&db).await.unwrap();let s=state(db,&root);let a=&e["active"];let b=&e["revoked"];assert_eq!(ok(&s,Some(access(a)),"GET","/auth/me",Value::Null).await["id"],"password-owner");denied(&s,Some(access(b)),"GET","/auth/me",Value::Null).await;denied(&s,None,"POST","/auth/refresh",json!({"refresh_token":refresh(b)})).await;let rows=ok(&s,Some(access(a)),"GET","/auth/sessions",Value::Null).await;assert_eq!(rows.as_array().unwrap().len(),1);assert_eq!(rows[0]["id"],sid(a));assert_eq!(rows[0]["is_current"],true);ok(&s,Some(access(a)),"DELETE",&format!("/auth/sessions/{}",sid(a)),Value::Null).await;denied(&s,Some(access(a)),"GET","/auth/me",Value::Null).await;denied(&s,None,"POST","/auth/refresh",json!({"refresh_token":refresh(a)})).await;let new=login(&s).await;assert_ne!(sid(&new),sid(a));assert!(ok(&s,Some(access(&new)),"GET","/spaces/password-space/documents/password-page/content",Value::Null).await["content"].as_str().unwrap().contains("EXACT_PASSWORD_PAGE Ω"));ok(&s,Some(access(&new)),"POST","/auth/logout",json!({})).await;denied(&s,Some(access(&new)),"GET","/auth/me",Value::Null).await;let count:i64=sqlx::query_scalar("SELECT COUNT(*) FROM sessions").fetch_one(&s.db).await.unwrap();assert_eq!(count,0);assert_eq!(serde_json::to_value(bytes(&root)).unwrap(),e["files"]);s.db.close().await;drop(s);println!("PASSWORD_ACTUAL_FRESH_RESTART_PASS");}
